parameters.command:
uip ixp deployments get-taxonomy --folder-key "c4359cde-55f0-4f0e-9322-c6cdce74ab4c" "invoiceixp-cef0d447-ixp" --output json 2>&1 > /tmp/ixp_taxonomy.json && python3 -c "
import json
with open('/tmp/ixp_taxonomy.json') as f:
    d = json.load(f)
dt = d.get('documentTaxonomy') or d.get('Data',{}).get('documentTaxonomy',{})
if dt:
    for doc in dt.get('documentTypes',[]):
        for field in doc.get('fields',[]):
            print(field.get('fieldName'), '|', field.get('type'))
else:
    print(json.dumps(d, indent=2)[:500])
" 2>&1

